BEGIN;

INSERT INTO public.places (slug, name, category, latitude, longitude, summary, description)
VALUES
  ('plaza-25-de-mayo', 'Plaza 25 de Mayo', 'Patrimonio cultural', -19.0479, -65.25952, 'Su nombre recuerda el levantamiento de Chuquisaca de 1809.', 'El nombre de la plaza principal de Sucre recuerda el levantamiento del 25 de mayo de 1809 en Chuquisaca. La normativa municipal relaciona este espacio con la memoria de las luchas emancipadoras y con la identidad de la ciudad. La Ley Nacional 531 de 2014 reconoció la Plaza 25 de Mayo como patrimonio cultural e histórico de Bolivia. La norma dispone que las autoridades competentes impulsen su preservación, restauración y promoción.'),
  ('casa-de-la-libertad', 'Casa de la Libertad', 'Patrimonio cultural', -19.04745, -65.26038, 'En su antiguo salón universitario se proclamó la independencia de Bolivia.', 'Antes de convertirse en museo, la Casa de la Libertad perteneció al conjunto jesuita destinado a la enseñanza. Su antigua capilla universitaria también funcionaba como sala para ceremonias académicas y defensas de tesis de los aspirantes a doctor. La Universidad de San Francisco Xavier de Chuquisaca fue fundada en 1624. En julio de 1825 se reunieron diputados de las cinco provincias del Alto Perú para decidir el futuro político del territorio. El 6 de agosto de 1825 proclamaron la independencia, dando origen a Bolivia. El actual Salón de la Independencia conserva la memoria de ese acontecimiento.'),
  ('la-recoleta', 'La Recoleta', 'Patrimonio cultural', -19.05451, -65.25398, 'Un antiguo convento franciscano junto a un mirador en el barrio Santa Ana.', 'La Recoleta está en el barrio Santa Ana, a los pies del cerro Churuquella. Según la Ordenanza Municipal 069/00, los franciscanos fundaron el convento en 1600; una publicación municipal sitúa la fundación del barrio en 1601. Las referencias describen dos entidades distintas, por lo que no se debe confundir una fecha con la otra. El Gobierno Municipal documentó intervenciones para recuperar el aspecto de la plazuela y el mirador: reparaciones de cubiertas, pavimentos e iluminación, y recuperación de la pileta conocida como La Peregrina. Estas acciones ayudan a conservar detalles arquitectónicos y el espacio de encuentro público.')
ON CONFLICT (slug) DO UPDATE SET
  category = CASE WHEN places.category = '[TEXTO DE EJEMPLO]' THEN EXCLUDED.category ELSE places.category END,
  summary = CASE WHEN places.summary = '[TEXTO DE EJEMPLO]' THEN EXCLUDED.summary ELSE places.summary END,
  description = CASE WHEN places.description = '[TEXTO DE EJEMPLO]' THEN EXCLUDED.description ELSE places.description END
WHERE '[TEXTO DE EJEMPLO]' IN (places.category, places.summary, places.description);

INSERT INTO public.questions (place_slug, position, prompt, options, correct_index, explanation)
VALUES
  ('plaza-25-de-mayo', 1, '¿Qué acontecimiento recuerda el nombre de la plaza?', '[{"optionId": "A", "text": "La proclamación de 1825"}, {"optionId": "B", "text": "El levantamiento de Chuquisaca de 1809"}, {"optionId": "C", "text": "La fundación de la Universidad en 1624"}]'::jsonb, 1, 'El nombre remite al levantamiento del 25 de mayo de 1809.'),
  ('plaza-25-de-mayo', 2, '¿Qué ley nacional reconoció a la plaza como patrimonio cultural e histórico de Bolivia?', '[{"optionId": "A", "text": "Ley 531 de 2014"}, {"optionId": "B", "text": "Ley 471 de 2025"}, {"optionId": "C", "text": "Ordenanza 069/00"}]'::jsonb, 0, 'La Ley Nacional 531 la reconoció en 2014.'),
  ('plaza-25-de-mayo', 3, '¿Qué elemento forma parte del diseño histórico de la plaza?', '[{"optionId": "A", "text": "Una muralla defensiva"}, {"optionId": "B", "text": "Un claustro franciscano"}, {"optionId": "C", "text": "Recorridos diagonales y circulares"}]'::jsonb, 2, 'La plaza conserva recorridos diagonales y circulares vinculados al diseño de influencia francesa.'),
  ('casa-de-la-libertad', 1, '¿Cuándo se proclamó la independencia de Bolivia?', '[{"optionId": "A", "text": "6 de agosto de 1825"}, {"optionId": "B", "text": "25 de mayo de 1809"}, {"optionId": "C", "text": "6 de agosto de 1898"}]'::jsonb, 0, 'Los diputados proclamaron la independencia el 6 de agosto de 1825.'),
  ('casa-de-la-libertad', 2, '¿Qué actividad se hacía en la antigua capilla universitaria?', '[{"optionId": "A", "text": "Sesiones del Concejo Municipal"}, {"optionId": "B", "text": "Restauración de fuentes"}, {"optionId": "C", "text": "Defensas de tesis"}]'::jsonb, 2, 'La antigua capilla fue escenario de ceremonias académicas y defensas de tesis.'),
  ('casa-de-la-libertad', 3, '¿Qué institución usó el edificio como sede hasta 1898?', '[{"optionId": "A", "text": "La UNESCO"}, {"optionId": "B", "text": "El Congreso"}, {"optionId": "C", "text": "El Concejo Municipal"}]'::jsonb, 1, 'El Congreso ocupó el edificio después de la independencia y hasta 1898.'),
  ('la-recoleta', 1, '¿Qué orden religiosa fundó el convento de La Recoleta?', '[{"optionId": "A", "text": "Jesuitas"}, {"optionId": "B", "text": "Dominicos"}, {"optionId": "C", "text": "Franciscanos"}]'::jsonb, 2, 'La Ordenanza Municipal 069/00 atribuye la fundación del convento a los franciscanos.'),
  ('la-recoleta', 2, '¿Cómo se llama la pileta recuperada en la plazuela?', '[{"optionId": "A", "text": "La Peregrina"}, {"optionId": "B", "text": "La Universitaria"}, {"optionId": "C", "text": "La Libertad"}]'::jsonb, 0, 'La restauración municipal incluyó la pileta conocida como La Peregrina.'),
  ('la-recoleta', 3, '¿Qué reconocimiento recuerda la placa conmemorativa presentada en La Recoleta?', '[{"optionId": "A", "text": "La fundación de la Universidad en 1624"}, {"optionId": "B", "text": "La inscripción de Sucre como Patrimonio Mundial en 1991"}, {"optionId": "C", "text": "La proclamación de la independencia en 1825"}]'::jsonb, 1, 'La placa recuerda el reconocimiento de Sucre como Patrimonio Mundial en 1991.')
ON CONFLICT (place_slug, position) DO UPDATE SET
  prompt = EXCLUDED.prompt,
  options = EXCLUDED.options,
  correct_index = EXCLUDED.correct_index,
  explanation = EXCLUDED.explanation
WHERE questions.prompt = '[TEXTO DE EJEMPLO]';

INSERT INTO public.sources (place_slug, title, url, institution, consulted_at, excerpt)
SELECT incoming.place_slug, incoming.title, incoming.url, incoming.institution, incoming.consulted_at, incoming.excerpt
FROM (VALUES
  ('plaza-25-de-mayo', 'Ley Autonómica Municipal 471/2025', 'https://gacetamunicipalsucre.gob.bo/docs/normas/ley/40693/LEY-471-2025-1751642062.pdf', 'Concejo Municipal de Sucre — Gaceta Municipal', '2026-11-27T00:00:00Z'::timestamptz, 'El nombre de la plaza principal de Sucre recuerda el levantamiento del 25 de mayo de 1809 en Chuquisaca. La normativa municipal relaciona este espacio con la memoria de las luchas emancipadoras y con la identidad de la ciudad.'),
  ('plaza-25-de-mayo', 'Ley N.º 531 — Declaración de patrimonio cultural de la Plaza 25 de Mayo', 'https://www.lexivox.org/norms/BO-L-N531.xhtml', 'Estado Plurinacional de Bolivia (texto reproducido por Lexivox)', '2026-11-27T00:00:00Z'::timestamptz, 'La Ley Nacional 531 de 2014 reconoció la Plaza 25 de Mayo como patrimonio cultural e histórico de Bolivia. La norma dispone que las autoridades competentes impulsen su preservación, restauración y promoción.'),
  ('casa-de-la-libertad', 'Historia de la Casa de la Libertad', 'https://casadelalibertad.org.bo/historia/', 'Casa de la Libertad — Fundación Cultural del Banco Central de Bolivia', '2026-11-27T00:00:00Z'::timestamptz, 'Antes de convertirse en museo, la Casa de la Libertad perteneció al conjunto jesuita destinado a la enseñanza. Su antigua capilla universitaria también funcionaba como sala para ceremonias académicas y defensas de tesis de los aspirantes a doctor. La Universidad de San Francisco Xavier de Chuquisaca fue fundada en 1624.'),
  ('casa-de-la-libertad', 'Historic City of Sucre', 'https://whc.unesco.org/en/list/566/', 'UNESCO World Heritage Centre', '2026-11-27T00:00:00Z'::timestamptz, 'Antes de convertirse en museo, la Casa de la Libertad perteneció al conjunto jesuita destinado a la enseñanza. Su antigua capilla universitaria también funcionaba como sala para ceremonias académicas y defensas de tesis de los aspirantes a doctor. La Universidad de San Francisco Xavier de Chuquisaca fue fundada en 1624.'),
  ('casa-de-la-libertad', 'Casa de la Libertad — Guía turística del Bicentenario', 'https://bicentenariocpe.tcpbolivia.bo/guia-turistica/lugar/casa-de-la-libertad', 'Tribunal Constitucional Plurinacional', '2026-11-27T00:00:00Z'::timestamptz, 'En julio de 1825 se reunieron diputados de las cinco provincias del Alto Perú para decidir el futuro político del territorio. El 6 de agosto de 1825 proclamaron la independencia, dando origen a Bolivia. El actual Salón de la Independencia conserva la memoria de ese acontecimiento.'),
  ('la-recoleta', 'La plazuela de La Recoleta luce una nueva imagen colonial', 'https://sucre.bo/la-plazuela-de-la-recoleta-luce-una-nueva-imagen-colonial/', 'Gobierno Autónomo Municipal de Sucre', '2026-11-27T00:00:00Z'::timestamptz, 'La Recoleta está en el barrio Santa Ana, a los pies del cerro Churuquella. Según la Ordenanza Municipal 069/00, los franciscanos fundaron el convento en 1600; una publicación municipal sitúa la fundación del barrio en 1601. Las referencias describen dos entidades distintas, por lo que no se debe confundir una fecha con la otra.'),
  ('la-recoleta', 'Ordenanza Municipal 069/00', 'https://gacetamunicipalsucre.gob.bo/docs/normas/ordenanza/34487/om-069-00.pdf', 'Concejo Municipal de Sucre — Gaceta Municipal', '2026-11-27T00:00:00Z'::timestamptz, 'La Recoleta está en el barrio Santa Ana, a los pies del cerro Churuquella. Según la Ordenanza Municipal 069/00, los franciscanos fundaron el convento en 1600; una publicación municipal sitúa la fundación del barrio en 1601. Las referencias describen dos entidades distintas, por lo que no se debe confundir una fecha con la otra.'),
  ('la-recoleta', 'Descubrimiento de la plaqueta conmemorativa Sucre Patrimonio Cultural de la Humanidad en La Recoleta', 'https://sucre.bo/descubrimiento-de-la-plaqueta-conmemorativa-sucre-patrimonio-cultural-de-la-humanidad-en-la-recoleta/', 'Gobierno Autónomo Municipal de Sucre', '2026-11-27T00:00:00Z'::timestamptz, 'En octubre de 2022 la Alcaldía presentó una placa conmemorativa en La Recoleta, ubicada en el muro del Museo de Tanga Tanga. La placa recuerda el reconocimiento de Sucre como Patrimonio Mundial en 1991 y busca sensibilizar a la población sobre el cuidado del legado arquitectónico.'),
  ('la-recoleta', 'Historic City of Sucre', 'https://whc.unesco.org/en/list/566/', 'UNESCO World Heritage Centre', '2026-11-27T00:00:00Z'::timestamptz, 'En octubre de 2022 la Alcaldía presentó una placa conmemorativa en La Recoleta, ubicada en el muro del Museo de Tanga Tanga. La placa recuerda el reconocimiento de Sucre como Patrimonio Mundial en 1991 y busca sensibilizar a la población sobre el cuidado del legado arquitectónico.')
) AS incoming(place_slug, title, url, institution, consulted_at, excerpt)
WHERE NOT EXISTS (
  SELECT 1 FROM public.sources AS existing
  WHERE existing.place_slug = incoming.place_slug AND existing.url = incoming.url
);

COMMIT;
